public class PowerOfThree {
    public static boolean isPowerOfThree(int n) {
        // Handle edge cases
        if (n < 1) return false;

        // Iterate through powers of three
        while (n != 1) {
            if (n % 3 != 0) return false; // If n is not divisible by 3, it's not a power of three

            // Divide n by 3
            n /= 3;
        }

        return true; // If all divisions result in 1, n is a power of three
    }

